function m(s,t){const c=[];if(!t)return c;const l=s?s.split("$$$"):[];return t.split("$$$").forEach((p,r)=>{const n={name:r<l.length&&l[r]?l[r]:`线路 ${r+1}`,direct:!1,eps:[]};p.split("#").forEach((e,d)=>{if(e=e.trim(),!e)return;let f=`第 ${d+1} 集`,i=e;const u=e.indexOf("$");u>0&&(f=e.slice(0,u).trim(),i=e.slice(u+1).trim()),i&&i.includes("://")&&n.eps.push({name:f,url:i,urls:[i]})});let o=0;n.eps.forEach(e=>{h(e.url)&&o++}),n.direct=n.eps.length>0&&o*2>=n.eps.length,n.eps.length&&c.push(n)}),c}function h(s){const t=s.toLowerCase();return t.includes(".m3u8")||t.includes(".mp4")||t.includes(".flv")||t.includes(".mkv")||t.includes(".ts")||t.includes(".m4v")}export{m as s};
